import { SuperSupabase } from "./supabase";
export class Issue extends SuperSupabase {
    constructor(supabase, context) {
        super(supabase, context);
    }
    async getIssue(issueNodeId) {
        const { data, error } = await this.supabase.from("issues").select("*").eq("id", issueNodeId);
        if (error) {
            this.context.logger.error("Error getting issue", {
                Error: error,
                issueData: {
                    id: issueNodeId,
                },
            });
            return null;
        }
        return data;
    }
    async findSimilarIssues({ markdown, currentId, threshold }) {
        // Create a new issue embedding
        try {
            const embedding = await this.context.adapters.voyage.embedding.createEmbedding(markdown);
            const { data, error } = await this.supabase.rpc("find_similar_issues_annotate", {
                query_embedding: embedding,
                current_id: currentId,
                threshold,
                top_k: 5,
            });
            if (error) {
                this.context.logger.error("Unable to find similar issues", {
                    Error: error,
                    markdown,
                    currentId,
                    threshold,
                    query_embedding: embedding,
                });
                return null;
            }
            return data;
        }
        catch (error) {
            this.context.logger.error("Unable to find similar issues", {
                Error: error,
                markdown,
                currentId,
                threshold,
            });
            return null;
        }
    }
    async findSimilarIssuesToMatch({ markdown, currentId, threshold }) {
        // Create a new issue embedding
        try {
            const embedding = await this.context.adapters.voyage.embedding.createEmbedding(markdown);
            const { data, error } = await this.supabase.rpc("find_similar_issues_to_match", {
                current_id: currentId,
                query_embedding: embedding,
                threshold,
                top_k: 5,
            });
            if (error) {
                this.context.logger.error("Error finding similar issues", {
                    Error: error,
                    markdown,
                    threshold,
                    query_embedding: embedding,
                });
                return null;
            }
            return data;
        }
        catch (error) {
            this.context.logger.error("Error finding similar issues", {
                Error: error,
                markdown,
                threshold,
            });
            return null;
        }
    }
}
